 "decisions": [
  {
   "title": "Data and called programs stay in the legacy databases",
   "context": "The procedure reads db_pagos, db_admin and db_cuentas and calls db_cuentas..sp_debito, which owns the account movement logic.",
   "decision": "Use data_strategy same_database: the target uses the legacy driver and qualified table names, and calls sp_debito through the generated DebitGateway adapter instead of reimplementing it.",
   "consequences": "No data migration. The debit logic and the order update remain in the same database server, so a single transaction can cover both."
  },
  {
   "title": "One transaction around debit, commission and order update",
   "context": "The legacy opens the transaction (line 108) just before the first debit and commits at line 161. The validations (lines 34-104) run outside it.",
   "decision": "PayOrder starts the transaction at the same point and uses a single connection for the sp_debito calls and the order update. Each of the three rollback points (lines 119, 136, 155) rolls back everything and rejects with DEBIT_FAILED, COMMISSION_FAILED or ORDER_UPDATE_FAILED. No savepoints exist, so no UnitOfWork port is needed.",
   "consequences": "A failure after the first debit also undoes the debit. Validation failures never open a transaction."
  },
  {
   "title": "Debit failures are signalled by the adapter",
   "context": "sp_debito returns a code (non-zero means failure) and an output sequence; the legacy also checks @@error after the first debit.",
   "decision": "DebitGateway.debitPayment returns the sequence (@o_secuencial); the adapter raises a debit failure on a non-zero return code or a database error. debitCommission raises on a non-zero return code. The use case maps these to DEBIT_FAILED and COMMISSION_FAILED.",
   "consequences": "The use case has no return-code plumbing; the movement is only exposed when the first debit succeeds."
  },
  {
   "title": "Money arithmetic and legacy null behaviour preserved",
   "context": "Amounts are money (decimal(19,4)). The WEB commission is round(tariff/2, 2). When the account is not found, the legacy balance stays NULL, so the funds comparison is false and the flow continues to the debit.",
   "decision": "Use BigDecimal with scale 4, rounding the WEB commission to 2 decimals HALF_UP. An empty Account result skips the funds check, exactly like the legacy. A null tariff becomes 0. A missing tar_separada is treated as in the legacy (null is not 'S', so the commission is included). The NOMINA exemption is applied last. The canal default 'WEB' is applied when the input is omitted.",
   "consequences": "Behaviour matches the golden master. For a non-existent account, the rejection comes from sp_debito (DEBIT_FAILED), as in the legacy."
  },
  {
   "title": "Error-logging infrastructure not translated",
   "context": "The ERROR label calls cobis..sp_cerror to register the error and returns @w_error.",
   "decision": "Rejections are modelled as business errors with stable codes and the legacy codes; sp_cerror is not called.",
   "consequences": "Error registration in cobis is replaced by service exceptions and logging."
  }
 ],
 "masks": [],
 "infrastructure": [
  "cobis..sp_cerror"
 ],
 "data_strategy": "same_database"
}

Rules:
[
 {
  "id": "RULE-001",
  "name": "Permitted account types for order payment",
  "category": "validation",
  "priority": "P0",
  "statement": "An order payment is only accepted for account types 'CTE', 'AHO' or 'VIR'. Any other account type is rejected with error 50001 and the message 'TIPO DE CUENTA NO PERMITIDO'.",
  "condition": "@i_tipo_cuenta not in ('CTE', 'AHO', 'VIR')",
  "action": "Set @w_error = 50001 and @o_mensaje = 'TIPO DE CUENTA NO PERMITIDO'.",
  "inputs": [
   {
    "name": "@i_tipo_cuenta",
    "type": "text(fixed,3,iso8859-1)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "@w_error",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@o_mensaje",
    "type": "text(var,120,iso8859-1)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Account type is permitted\n  Given @i_tipo_cuenta is 'AHO'\n  When the payment order is validated\n  Then no error is raised for the account type",
   "Scenario: Account type is not permitted\n  Given @i_tipo_cuenta is 'PRE'\n  When the payment order is validated\n  Then @w_error is 50001 and @o_mensaje is 'TIPO DE CUENTA NO PERMITIDO'"
  ],
  "sources": [
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 34,
    "line_end": 37
   }
  ]
 },
 {
  "id": "RULE-002",
  "name": "Only pending orders can be paid",
  "category": "validation",
  "priority": "P0",
  "statement": "A payment order can only be processed if its status is 'P' (pending). If the order is in any other status, it is rejected with error 50003 and the message 'ORDEN NO ESTA PENDIENTE'.",
  "condition": "ord_estado of the order (ord_numero = @i_orden, ord_empresa = @i_empresa) in db_pagos..pg_orden <> 'P'",
  "action": "Set @w_error = 50003 and @o_mensaje = 'ORDEN NO ESTA PENDIENTE'.",
  "inputs": [
   {
    "name": "@i_empresa",
    "type": "text(fixed,3,iso8859-1)",
    "description": ""
   },
   {
    "name": "@i_orden",
    "type": "text(fixed,10,iso8859-1)",
    "description": ""
   },
   {
    "name": "ord_estado",
    "type": "text(fixed,1,iso8859-1)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "@w_error",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@o_mensaje",
    "type": "text(var,120,iso8859-1)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Pending order passes the check\n  Given order 'ORD0000001' of company 'E01' has status 'P'\n  When the payment of the order is requested\n  Then no error 50003 is raised and processing may continue",
   "Scenario: Non-pending order is rejected\n  Given order 'ORD0000001' of company 'E01' has status 'C'\n  When the payment of the order is requested\n  Then error 50003 is set\n  And the message is 'ORDEN NO ESTA PENDIENTE'"
  ],
  "sources": [
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 42,
    "line_end": 45
   },
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 54,
    "line_end": 57
   }
  ]
 },
 {
  "id": "RULE-003",
  "name": "Payment requires an existing order",
  "category": "validation",
  "priority": "P0",
  "statement": "A payment cannot be processed for an order that does not exist. When the order lookup returns no rows, the procedure reports error 50002 with the message 'ORDEN NO EXISTE'.",
  "condition": "The preceding query (not shown in this slice) affected or returned zero rows (@@rowcount = 0).",
  "action": "Set @w_error = 50002 and @o_mensaje = 'ORDEN NO EXISTE'.",
  "inputs": [
   {
    "name": "@@rowcount",
    "type": "integer(32,signed)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "@w_error",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@o_mensaje",
    "type": "text(var,120,iso8859-1)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Order not found\n  Given the order lookup for the payment returns no rows\n  When the payment procedure evaluates the result\n  Then the error code is 50002\n  And the message is 'ORDEN NO EXISTE'",
   "Scenario: Order found\n  Given the order lookup returns one row\n  When the payment procedure evaluates the result\n  Then error 50002 is not raised by this check"
  ],
  "sources": [
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 47,
    "line_end": 50
   }
  ]
 },
 {
  "id": "RULE-004",
  "name": "Company-specific service tariff with default fallback",
  "category": "calculation",
  "priority": "P0",
  "statement": "The service tariff is taken from the company-specific tariff for the service, together with its 'charged separately' flag. If the company has no specific tariff, the service's default tariff applies and the commission is never charged separately ('N'). A missing tariff is treated as 0.",
  "condition": "A row exists in ad_tarifa_empresa for tar_empresa = @i_empresa and tar_servicio = @i_servicio; otherwise (@@rowcount = 0) use ad_servicio where srv_codigo = @i_servicio; if the resulting tariff is null.",
  "action": "With a company row: tariff = tar_valor and separada = tar_separada. Without one: tariff = srv_tarifa and separada = 'N'. If the tariff is still null, tariff = 0.",
  "inputs": [
   {
    "name": "@i_empresa",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@i_servicio",
    "type": "text(var,10,iso8859-1)",
    "description": ""
   },
   {
    "name": "tar_valor",
    "type": "decimal(19,4,signed)",
    "description": ""
   },
   {
    "name": "tar_separada",
    "type": "text(fixed,1,iso8859-1)",
    "description": ""
   },
   {
    "name": "srv_tarifa",
    "type": "decimal(19,4,signed)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "@w_tarifa",
    "type": "decimal(19,4,signed)",
    "description": ""
   },
   {
    "name": "@w_separada",
    "type": "text(fixed,1,iso8859-1)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Company-specific tariff\n Given company 15 has a tariff of 2.00 for service 'LUZ' with separada 'S'\n When the payment is processed\n Then the tariff is 2.00 and separada is 'S'",
   "Scenario: Fallback to the service default\n Given company 15 has no tariff row for service 'AGUA' and the service default tariff is 1.50\n When the payment is processed\n Then the tariff is 1.50 and separada is 'N'",
   "Scenario: Missing tariff\n Given the tariff found is null\n When the payment is processed\n Then the tariff is 0"
  ],
