        String tipoCuenta = request.tipoCuenta();

        // RULE-001
        if (!("CTE".equals(tipoCuenta) || "AHO".equals(tipoCuenta) || "VIR".equals(tipoCuenta))) {
            throw new BusinessError("ACCOUNT_TYPE_NOT_ALLOWED", "50001", "TIPO DE CUENTA NO PERMITIDO");
        }

        // RULE-003
        Optional<PaymentOrder> order = orderRepository.findByNumberAndCompany(request.orden(), request.empresa());
        if (order.isEmpty()) {
            throw new BusinessError("ORDER_NOT_FOUND", "50002", "ORDEN NO EXISTE");
        }

        // RULE-002
        if (!"P".equals(order.get().ordEstado())) {
            throw new BusinessError("ORDER_NOT_PENDING", "50003", "ORDEN NO ESTA PENDIENTE");
        }

        // RULE-004 / RULE-005
        BigDecimal tarifa;
        String separada;
        Optional<CompanyTariff> companyTariff =
                companyTariffRepository.findByCompanyAndService(request.empresa(), request.servicio());
        if (companyTariff.isPresent()) {
            tarifa = companyTariff.get().tarValor();
            separada = companyTariff.get().tarSeparada();
        } else {
            Optional<ServiceCatalog> service = serviceRepository.findByCode(request.servicio());
            tarifa = service.map(ServiceCatalog::srvTarifa).orElse(null);
            separada = "N";
        }
        if (tarifa == null) {
            tarifa = BigDecimal.ZERO;
        }

        // RULE-006
        String canal = request.canal() == null ? "WEB" : request.canal();
        BigDecimal comision;
        if ("WEB".equals(canal)) {
            comision = tarifa.divide(new BigDecimal("2"), 2, RoundingMode.HALF_UP);
        } else {
            comision = tarifa;
        }
        if ("NOMINA".equals(request.servicio())) {
            comision = BigDecimal.ZERO;
        }
        comision = comision.setScale(4, RoundingMode.HALF_UP);

        // RULE-007
        boolean comisionSeparada = "S".equals(separada);
        BigDecimal total = comisionSeparada ? request.valor() : request.valor().add(comision);

        // RULE-008 (a missing account leaves the balance NULL: the check is skipped)
        Optional<Account> account = accountRepository.findByNumberAndType(request.cuenta(), tipoCuenta);
        if (account.isPresent() && account.get().ctaSaldo() != null) {
            BigDecimal saldo = account.get().ctaSaldo();
            boolean insufficient;
            if ("VIR".equals(tipoCuenta)) {
                insufficient = saldo.compareTo(total) < 0;
            } else {
                insufficient = saldo.add(OVERDRAFT_MARGIN).compareTo(total) < 0;
            }
            if (insufficient) {
                throw new BusinessError("INSUFFICIENT_FUNDS", "50004", "FONDOS INSUFICIENTES");
            }
        }

        // RULE-009
        int movimiento = debitGateway.debitPayment(request.cuenta(), tipoCuenta, total, "PAGO ORDEN");

        // RULE-010 / RULE-011
        if (comisionSeparada && comision.compareTo(BigDecimal.ZERO) > 0) {
            debitGateway.debitCommission(request.cuenta(), tipoCuenta, comision, "COMISION PAGO");
        }

        // RULE-012 / RULE-013 / RULE-014
        int rows = orderRepository.markPaid(request.orden(), request.empresa(), request.fechaProceso(), comision);
        if (rows == 0) {
            throw new BusinessError("ORDER_UPDATE_FAILED", "50007", "ERROR ACTUALIZANDO ORDEN");
        }

        // RULE-015
        return new PayOrderResponse(movimiento, "PAGO REALIZADO");
    }
}
